```python
import random
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.bot_ai import BotAI
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.position import Point2

class ProtossBot(BotAI):
    async def on_step(self, iteration):
        # If no Nexus left, try to fight with what we have
        if not self.townhalls:
            await self.all_army_attack()
            return

        await self.distribute_workers()
        await self.build_pylons()
        await self.train_probes()
        await self.build_assimilators()
        await self.build_gateway()
        await self.build_cybercore()
        await self.research_warpgate()
        await self.morph_gateways()
        await self.warp_units()
        await self.build_proxy_pylon()
        await self.chrono_boost()
        await self.all_army_attack()

    async def build_pylons(self):
        if (
            self.supply_left < 5
            and self.already_pending(UnitTypeId.PYLON) == 0
            and self.can_afford(UnitTypeId.PYLON)
        ):
            nex = self.townhalls.ready.random_or(None)
            if nex:
                pos = nex.position.towards(self.game_info.map_center, 5)
                await self.build(UnitTypeId.PYLON, near=pos)

    async def train_probes(self):
        for nexus in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.PROBE) and self.workers.amount < self.townhalls.amount * 22:
                nexus.train(UnitTypeId.PROBE)

    async def build_assimilators(self):
        for nexus in self.townhalls.ready:
            vgs = self.vespene_geyser.closer_than(10, nexus)
            for vg in vgs:
                if not self.gas_buildings.closer_than(1, vg):
                    worker = self.select_build_worker(vg.position)
                    if worker and self.can_afford(UnitTypeId.ASSIMILATOR):
                        worker.build(UnitTypeId.ASSIMILATOR, vg)
                        break

    async def build_gateway(self):
        if (
            self.structures(UnitTypeId.PYLON).ready
            and self.structures(UnitTypeId.GATEWAY).amount + self.already_pending(UnitTypeId.GATEWAY) < 2
            and self.can_afford(UnitTypeId.GATEWAY)
        ):
            pylon = self.structures(UnitTypeId.PYLON).ready.random
            await self.build(UnitTypeId.GATEWAY, near=pylon)

    async def build_cybercore(self):
        if (
            self.structures(UnitTypeId.GATEWAY).ready
            and not self.structures(UnitTypeId.CYBERNETICSCORE)
            and self.can_afford(UnitTypeId.CYBERNETICSCORE)
        ):
            pylon = self.structures(UnitTypeId.PYLON).ready.random
            await self.build(UnitTypeId.CYBERNETICSCORE, near=pylon)

    async def research_warpgate(self):
        cybercore = self.structures(UnitTypeId.CYBERNETICSCORE).ready
        if cybercore and self.can_afford(AbilityId.RESEARCH_WARPGATE) and not self.already_pending_upgrade(UpgradeId.WARPGATERESEARCH):
            abilities = await self.get_available_abilities(cybercore.first)
            if AbilityId.RESEARCH_WARPGATE in abilities:
                cybercore.first.research(UpgradeId.WARPGATERESEARCH)

    async def morph_gateways(self):
        if self.has_upgrade(UpgradeId.WARPGATERESEARCH):
            for gw in self.structures(UnitTypeId.GATEWAY).ready:
                abilities = await self.get_available_abilities(gw)
                if AbilityId.MORPH_WARPGATE in abilities:
                    gw(AbilityId.MORPH_WARPGATE)

    async def warp_units(self):
        if not self.has_upgrade(UpgradeId.WARPGATERESEARCH):
            # Train stalkers from gateways if warpgate not researched
            for gw in self.structures(UnitTypeId.GATEWAY).ready.idle:
                if self.can_afford(UnitTypeId.STALKER):
                    gw.train(UnitTypeId.STALKER)
            return

        warpgates = self.structures(UnitTypeId.WARPGATE).ready
        if warpgates:
            for wg in warpgates.idle:
                if self.can_afford(UnitTypeId.STALKER):
                    pos = await self.find_placement(
                        AbilityId.WARPGATETRAIN_STALKER,
                        self.structures(UnitTypeId.PYLON).ready.random.position,
                        placement_step=2,
                    )
                    if pos:
                        wg.warp_in(UnitTypeId.STALKER, pos)

    async def build_proxy_pylon(self):
        # Build proxy pylon near enemy base if we don't have one
        proxy_pylons = self.structures(UnitTypeId.PYLON).closer_than(20, self.enemy_start_locations[0])
        if proxy_pylons.amount == 0 and self.can_afford(UnitTypeId.PYLON):
            pos = self.enemy_start_locations[0].towards(self.game_info.map_center, 20)
            await self.build(UnitTypeId.PYLON, near=pos)

    async def chrono_boost(self):
        for nexus in self.townhalls.ready:
            if nexus.energy >= 50:
                # Prioritize chrono boosting cybercore, then nexus
                cybercore = self.structures(UnitTypeId.CYBERNETICSCORE).ready
                if cybercore and not self.has_upgrade(UpgradeId.WARPGATERESEARCH):
                    abilities = await self.get_available_abilities(nexus)
                    if AbilityId.EFFECT_CHRONOBOOST in abilities:
                        nexus(AbilityId.EFFECT_CHRONOBOOST, cybercore.first)
                        return
                abilities = await self.get_available_abilities(nexus)
                if AbilityId.EFFECT_CHRONOBOOST in abilities:
                    nexus(AbilityId.EFFECT_CHRONOBOOST, nexus)
                    return

    async def all_army_attack(self):
        army = self.units.of_type({UnitTypeId.STALKER, UnitTypeId.ZEALOT, UnitTypeId.ADEPT, UnitTypeId.SENTRY, UnitTypeId.IMMORTAL, UnitTypeId.ARCHON, UnitTypeId.COLOSSUS, UnitTypeId.DISRUPTOR, UnitTypeId.HIGHTEMPLAR, UnitTypeId.DARKTEMPLAR, UnitTypeId.PHOENIX, UnitTypeId.VOIDRAY, UnitTypeId.CARRIER, UnitTypeId.TEMPEST, UnitTypeId.ORACLE, UnitTypeId.WARPPRISM, UnitTypeId.OBSERVER, UnitTypeId.MOTHERSHIP, UnitTypeId.MOTHERSHIPCORE})
        if army.amount > 0:
            targets = self.enemy_units | self.enemy_structures
            if targets:
                target = targets.closest_to(army.center)
                for unit in army.idle:
                    unit.attack(target)
            else:
                for unit in army.idle:
                    unit.attack(self.enemy_start_locations[0])

def main():
    run_game(
        maps.get("(2)CatalystLE"),
        [
            Bot(Race.Protoss, ProtossBot()),
            Computer(Race.Protoss, Difficulty.Easy)
        ],
        realtime=False,
    )

if __name__ == "__main__":
    main()
